class Solution 
{
public:
    void setZeroes(vector<vector<int>>& matrix) 
    {
        int i = 0 ;
        int j = 0 ;
        size_t row = matrix.size() ;
        size_t col = matrix[0].size() ;
        bool col_zero_check = 1; 
        for(i=0;i<row;i++)
        {
            if(matrix[i][0] == 0)
            {
                col_zero_check = 0 ;
            }
            for(j=1;j<col;j++)
            {
                if(matrix[i][j] == 0)
                {
                    matrix[0][j] = 0 ;
                    matrix[i][0] = 0 ;
                }
            }
        }
        for(i=row-1;i>=0;i--)
        {
            for(j=col-1;j>=1;j--)
            {
                if( (matrix[0][j]==0) || (matrix[i][0] ==0) )
                {
                    matrix[i][j] = 0 ;
                }
            }
            if(col_zero_check ==0)
            {
                matrix[i][0] = 0 ;
            }
        }   
    }
};
